$('panel').addEventListener('input',e=>{const a=e.target.closest('article');if(!a)return;const r=project().students.find(x=>x.id===a.dataset.id);if(r.confirmed)return;if(e.target.hasAttribute('data-note')){r.note=e.target.value;changed(r);refreshPreview(r);refreshProgress(r,a);}else if(e.target.hasAttribute('data-comment')){if(!r.manualDraft)rememberVersion(r);r.generationError='';r.comment=e.target.value;r.manualDraft=true;choices.delete(r.id);a.querySelector('[data-choice-panel]').innerHTML='';r.aiWarnings=[];r.semanticChecked=false;r.qualityChecked=false;r.stale=false;r.rev=(r.rev||0)+1;clearTimeout(timers.get(r.id));r.pending=false;requests.delete(r.id);save();refreshPreview(r);refreshProgress(r,a);}});
$('panel').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.shiftKey&&!e.ctrlKey&&!e.altKey&&!e.metaKey&&!e.isComposing){const next=e.target.closest('article')?.querySelector('[data-next]');if(next&&!next.disabled){e.preventDefault();next.click();return;}}const cell=e.target.closest('[data-score]');if(!cell||cell.disabled||e.ctrlKey||e.altKey||e.metaKey)return;const a=cell.closest('article'),i=Number(cell.dataset.score.split(':')[0]);if(/^[1-5]$/.test(e.key)){e.preventDefault();a.querySelector(`[data-score="${i}:${e.key}"]`)?.click();const next=$('panel').querySelector('.student.open');next?.querySelector(i<5?`[data-score="${i+1}:${e.key}"]`:'[data-note]')?.focus();}else if(e.key==='Enter'&&e.shiftKey){e.preventDefault();a.querySelector('[data-next]')?.click();}});
$('panel').addEventListener('change',e=>{if(e.target.hasAttribute('data-comment')){const r=project().students.find(x=>x.id===e.target.closest('article').dataset.id);if(r&&!validate(r.comment,[]).length){archiveFeedback(r);save();}return;}if(!e.target.hasAttribute('data-student-id'))return;const r=project().students.find(x=>x.id===e.target.closest('article').dataset.id);if(!r||r.confirmed)return;const id=identity(e.target.value);if(id&&project().students.some(x=>x.id!==r.id&&identity(x.studentId).toUpperCase()===id.toUpperCase())){e.target.value=r.studentId;return toast('本班已有相同學號，請核對');}r.studentId=id;changed(r);render();});
