$('importBtn').onclick=()=>{$('importPreview').textContent='';$('importDialog').showModal();};$('previewImport').onclick=async()=>{try{const skipped=[],file=$('rosterFile').files[0],rows=file?await recordsFrom(file,skipped):mergeSheets([textRows($('rosterText').value)],{allowNames:true,skipped});const result=mergeRoster(project().students,rows);$('importPreview').textContent='辨識 '+rows.length+' 人；預計新增 '+result.added+' 人、補入 '+result.updated+' 人、衝突 '+result.conflicts+' 筆\n'+rows.slice(0,8).map(r=>r.seat+'　'+r.name+'　'+r.scores.filter(v=>v!==null).length+'/6 向度').join('\n')+(rows.length>8?'\n…':'')+(result.conflictDetails.length?'\n衝突明細：\n'+result.conflictDetails.join('\n'):'')+(skipped.length?'\n⚠ '+skippedSummary(skipped):'');}catch(e){$('importPreview').textContent=e.message;}};for(const id of ['rosterFile','rosterText'])$(id).addEventListener('input',()=>{$('importPreview').textContent='';});$('cancelImport').onclick=()=>$('importDialog').close();$('applyImport').onclick=async()=>{try{const skipped=[],file=$('rosterFile').files[0],incoming=file?await recordsFrom(file,skipped):mergeSheets([textRows($('rosterText').value)],{allowNames:true,skipped});if(!incoming.length)return toast(skipped.length?'沒有可匯入的學生。'+skippedSummary(skipped):'沒有可匯入的學生');const p=project();const comments=incoming.filter(r=>r.comment).length;const check=mergeRoster(p.students,incoming);if(check.conflicts&&!confirm('下列資料不會匯入：\n'+check.conflictDetails.join('\n')+'\n是否繼續？'))return;if(!confirm(`辨識 ${incoming.length} 位學生、${comments} 則既有評語。只補入空白欄位，不覆蓋既有評分及評語。`+(skipped.length?'\n\n⚠ '+skippedSummary(skipped):'')+'\n是否匯入？'))return;const merged=mergeRoster(p.students,incoming);for(const t of timers.values())clearTimeout(t);requests.clear();p.students=merged.students;for(const x of p.students){x.pending=false;if(db.instant&&!x.comment&&!x.confirmed&&complete(x.scores))changed(x);}const {added:n,updated,conflicts}=merged;save();render();$('importDialog').close();$('rosterText').value='';$('rosterFile').value='';toast(`新增 ${n} 人，補入 ${updated} 人，略過 ${conflicts} 筆姓名衝突`+(skipped.length?`；另有 ${skipped.length} 列因座號問題未匯入`:''));}catch(e){toast(e.message);}};
$('baseline').onclick=()=>{const input=prompt('輸入全班基準分數 1～5（只填補尚未評分的向度）','4');if(input===null)return;const score=Number(input);if(!Number.isInteger(score)||score<1||score>5)return toast('請輸入 1～5 的整數');if(!confirm('將未評分向度設為 '+score+' 分；保留已評分及已確認評語。完整評分將自動生成評語。'))return;let n=0;for(const r of project().students){if(r.confirmed||!r.scores.some(v=>v===null))continue;r.scores=r.scores.map(v=>v??score);changed(r);n++;}save();render();toast(`已填補 ${n} 位學生的空白向度`);};
