$('word').onclick=async()=>{try{if(!window.JSZip)throw Error('Word 函式庫未載入');const z=new JSZip();z.file('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');z.file('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');const rows=[['學號','座號','姓名','評語'],...exportRows()];z.file('word/document.xml',`<?xml version="1.0" encoding="UTF-8"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:r><w:t>${esc(project().name)} 期末評語</w:t></w:r></w:p><w:tbl><w:tblPr><w:tblBorders>${['top','left','bottom','right','insideH','insideV'].map(x=>`<w:${x} w:val="single" w:sz="4"/>`).join('')}</w:tblBorders></w:tblPr>${rows.map(row=>`<w:tr>${row.map((v,i)=>`<w:tc><w:tcPr><w:tcW w:w="${[1300,700,1500,5600][i]}" w:type="dxa"/></w:tcPr><w:p><w:r><w:t xml:space="preserve">${esc(v)}</w:t></w:r></w:p></w:tc>`).join('')}</w:tr>`).join('')}</w:tbl><w:sectPr/></w:body></w:document>`);download(await z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}),'期末評語.docx');}catch(e){toast(e.message);}};
$('backup').onclick=()=>{if(storageBlocked&&damagedRaw!==null){download(new Blob([damagedRaw],{type:'text/plain;charset=utf-8'}),'comment-helper-corrupt-'+localDate()+'.txt');return;}download(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),'comment-helper-backup-'+localDate()+'.json');};$('restore').onchange=async()=>{try{if(!$('restore').files[0])return;let x;try{x=JSON.parse(await $('restore').files[0].text());}catch{throw Error('備份檔不是有效的 JSON');}if(!validBackup(x))throw Error('備份格式錯誤');if(!confirm('還原將取代目前本機資料，是否繼續？'))return;for(const t of timers.values())clearTimeout(t);timers.clear();requests.clear();choices.clear();undoScores.clear();clearCandidateCache();db=x;storageBlocked=false;damagedRaw=null;semanticEditing=-1;db.active=db.projects.some(p=>p.id===db.active)?db.active:db.projects[0].id;db.feedback??=[];db.styleVersions??=[];db.endpoint='';db.shareHistory=false;for(const p of db.projects)for(const r of p.students){r.pending=false;r.manualDraft??=Boolean(r.aiOriginal&&r.comment&&r.aiOriginal!==r.comment);}save();render();renderHistory();queueMissing();toast('已還原備份');}catch(e){toast(e.message);}finally{$('restore').value='';}};
function showTab(t){for(const x of document.querySelectorAll('[data-tab],[data-go]'))x.setAttribute('aria-current',(x.dataset.tab||x.dataset.go)===t?'page':'false');for(const id of ['work','history','settings'])$(id).hidden=id!==t;if(t==='history')renderHistory();if(t==='work')render();if(t==='settings'){renderRosterAdmin();renderSemanticLibrary();}window.scrollTo(0,0);}for(const b of document.querySelectorAll('[data-tab],[data-go]'))b.onclick=()=>showTab(b.dataset.tab||b.dataset.go);save();render();

let editingStudent=null,editingProject=null;
function openStudentDialog(r,p=project()){editingStudent=r?.id||null;editingProject=p.id;$('studentDialogTitle').textContent=r?'修改學生基本資料':'手動新增學生';$('studentSeat').value=r?.seat||String(Math.max(0,...p.students.map(x=>Number(x.seat)||0))+1).padStart(2,'0');$('studentName').value=r?.name||'';$('studentId').value=r?.studentId||'';$('studentError').textContent='';$('studentDialog').showModal();}
