$('cancelStudent').onclick=()=>$('studentDialog').close();
$('saveStudent').onclick=()=>{const p=db.projects.find(x=>x.id===editingProject);if(!p)return $('studentDialog').close();const r=p.students.find(x=>x.id===editingStudent);if(editingStudent&&!r)return $('studentDialog').close();const candidate={seat:identity($('studentSeat').value),name:$('studentName').value.trim(),studentId:identity($('studentId').value)};const issue=identityConflict(p.students,candidate,editingStudent);if(issue){$('studentError').textContent=issue;return;}if(r){const idChanged=r.studentId!==candidate.studentId;Object.assign(r,candidate);if(idChanged){if(r.confirmed){r.confirmed=false;r.semanticChecked=false;r.qualityChecked=false;r.rated=false;r.stale=Boolean(r.comment);}changed(r);}}else{const newStudent={id:newId(),...candidate,scores:Array(6).fill(null),note:'',comment:'',rated:false,confirmed:false,legacy:{}};p.students.push(newStudent);p.open=newStudent.id;}p.students.sort((a,b)=>Number(a.seat)-Number(b.seat));save();render();renderRosterAdmin();$('studentDialog').close();};
