 $('styleMetrics').innerHTML=[['教師樣本',p.count+' 則'],['平均字數',p.features.averageLength+' 字'],['平均句段',s?s.clauses.toFixed(1):'—'],['分號使用',s?Math.round(s.semicolon*100)+'%':'—']].map(([k,v])=>'<div><small>'+esc(k)+'</small><strong>'+esc(v)+'</strong></div>').join('');
