let handoffBatchId='';function handoffData(){return createHandoff(project(),db.history,db.projects,profile(),{scope:$('handoffScope').value,names:$('handoffNames').checked,includeHistory:$('handoffHistory').checked,task:$('handoffTask').value,selected:[...$('handoffStudents').querySelectorAll('input:checked')].map(x=>x.value),batchId:handoffBatchId});}
function refreshHandoff(){$('handoffStudents').hidden=$('handoffScope').value!=='selected';const h=handoffData();$('handoffCommand').value=h.command;$('handoffSummary').textContent='預計提交 '+h.data.summary.targets+' 位；排除 '+h.data.summary.excluded+' 位（缺分、保護或未選取）。指令 v'+HANDOFF_VERSION;$('handoffPreview').textContent=JSON.stringify(h.data,null,2);$('downloadHandoff').disabled=!h.data.targets.length;}
