$('handoffBtn').onclick=openHandoff;$('settingsHandoff').onclick=openHandoff;$('closeHandoff').onclick=()=>$('handoffDialog').close();for(const id of ['handoffScope','handoffNames','handoffHistory','handoffTask','handoffStudents'])$(id).onchange=refreshHandoff;
$('copyHandoff').onclick=async()=>{try{await navigator.clipboard.writeText($('handoffCommand').value);toast('已複製交接命令');}catch{$('handoffCommand').select();toast('請複製已選取的交接命令');}};
$('downloadHandoff').onclick=()=>{const h=handoffData();if(!h.data.targets.length)return toast('目前沒有評分完整的待提交學生');const batch={id:handoffBatchId,projectId:project().id,task:h.data.task,at:new Date().toISOString(),mapping:h.mapping};db.handoffBatches??=[];db.handoffBatches.push(batch);save();download(new Blob([h.markdown],{type:'text/markdown;charset=utf-8'}),'comment-helper-評語交接-'+handoffBatchId+'.md');toast('已產生交接檔，請先檢查內容再自行提交');handoffBatchId='B'+newId().replaceAll('-','').slice(0,16).toUpperCase();refreshHandoff();};

function commentProgress(list){const n=list.filter(r=>complete(r.scores)&&!r.stale&&!r.pending&&validate(r.comment,historyFor(r)).length===0).length;$('commentProgressText').textContent=n+' / '+list.length+' 位';$('commentBar').style.width=(list.length?n/list.length*100:0)+'%';return n;}
function rememberVersion(r){if(!r.comment)return;const a=r.commentVersions??=[];if(a[0]?.comment!==r.comment)a.unshift({comment:r.comment,at:new Date().toISOString(),evidence:r.stale?null:JSON.stringify([r.scores,r.note,r.studentId||''])});}
function showVersions(r,a){a.querySelector('[data-choice-panel]').innerHTML='<div class="choice-panel"><div class="choice-title">評語歷史版本<button data-dismiss-choice>收合</button></div>'+((r.commentVersions||[]).map((v,i)=>'<div class="choice-row"><p>'+esc(v.comment)+'</p><button data-restore-version="'+i+'" '+''+'>復原</button></div>').join('')||'<p class="muted">尚無舊版本。</p>')+'</div>';}
function renderSemanticLibrary(){const rows=db.semanticRules||[];$('semanticList').innerHTML=rows.map((r,i)=>'<div class="semantic-row"><div><strong>'+esc(r.topic)+'</strong><p>'+esc(r.keywords.join('、'))+' → '+esc(r.phrase)+'</p><small>'+esc((r.kind==='positive'?'肯定描述':'成長期待')+' · '+(dims[r.dim]||'不限向度')+' · '+((r.grades||[]).join('、')||'不限等第')+' · 優先 '+(r.priority||0))+'</small></div><button data-sem-edit="'+i+'">編輯</button><button data-sem-toggle="'+i+'">'+(r.enabled===false?'啟用':'停用')+'</button></div>').join('')||'<p class="muted">尚未新增個人規則。內建規則持續生效。</p>';$('semanticBuiltin').textContent='共 '+builtinSemanticRules.length+' 條內建規則；依評量向度或關鍵字查詢。';renderBuiltinRules();}
let semanticEditing=-1;
function readSemanticRule(){return {topic:$('semanticTopic').value.trim(),keywords:$('semanticKeywords').value.split(/[、,，\n]/).map(x=>x.trim()).filter(Boolean),kind:$('semanticKind').value,dim:$('semanticDim').value===''?null:Number($('semanticDim').value),grades:$('semanticGrades').value.split(/[、,， ]/).filter(Boolean).map(Number),priority:Number($('semanticPriority').value),exclusions:$('semanticExclude').value.split(/[、,，]/).map(x=>x.trim()).filter(Boolean),phrase:$('semanticPhrase').value.trim(),enabled:semanticEditing>=0?db.semanticRules[semanticEditing].enabled!==false:true};}
$('semanticSave').onclick=()=>{const rule=readSemanticRule();if(!validSemanticRule(rule))return toast('請填入主題、辨識詞及 3～16 字的合宜描述');db.semanticRules??=[];if(semanticEditing>=0){(db.semanticRuleHistory??=[]).push({...db.semanticRules[semanticEditing],archivedAt:new Date().toISOString()});db.semanticRules[semanticEditing]=rule;}else db.semanticRules.push(rule);semanticEditing=-1;$('semanticTopic').value=$('semanticKeywords').value=$('semanticPhrase').value=$('semanticExclude').value=$('semanticGrades').value=$('semanticDim').value='';$('semanticPriority').value='0';save();renderSemanticLibrary();toast('已儲存語意規則，下一次生成時生效');};
$('semanticList').onclick=e=>{const b=e.target.closest('button');if(!b)return;const i=Number(b.dataset.semEdit??b.dataset.semToggle),r=db.semanticRules?.[i];if(!r)return;if(b.hasAttribute('data-sem-edit')){semanticEditing=i;$('semanticTopic').value=r.topic;$('semanticKeywords').value=r.keywords.join('、');$('semanticKind').value=r.kind;$('semanticDim').value=r.dim??'';$('semanticGrades').value=(r.grades||[]).join('、');$('semanticPriority').value=r.priority||0;$('semanticExclude').value=(r.exclusions||[]).join('、');$('semanticPhrase').value=r.phrase;}else{r.enabled=r.enabled===false;save();renderSemanticLibrary();}};

let classViewMode='scores';
function openClassView(mode){classViewMode=mode;renderClassView();$('classDialog').showModal();}
function renderClassView(){
 const list=project().students;$('classDialogTitle').textContent=classViewMode==='scores'?'全班快速評分':'全班評語編輯';
 $('classDialogHint').textContent=classViewMode==='scores'?'選擇 1–5 或使用數字鍵；方向鍵移動，完整評分自動生成。':'直接編輯、即時儲存；不需要逐筆確認。已保護的評語須先解除保護。';
 $('classView').innerHTML=classViewMode==='scores'?'<div class="matrix-scroll"><table class="matrix"><thead><tr><th>學生</th>'+dims.map(d=>'<th>'+esc(d)+'</th>').join('')+'</tr></thead><tbody>'+list.map((r,i)=>'<tr><th>'+esc(r.seat+' '+r.name)+'</th>'+r.scores.map((v,j)=>'<td><select data-matrix="'+i+':'+j+'" aria-label="'+esc(r.name+' '+dims[j])+'" '+''+' style="background:'+(v?pale[v-1]:'#fff')+'"><option value="">—</option>'+[5,4,3,2,1].map(n=>'<option value="'+n+'" '+(v===n?'selected':'')+'>'+n+'</option>').join('')+'</select></td>').join('')+'</tr>').join('')+'</tbody></table></div>':list.map((r,i)=>'<div class="class-comment-row"><div><strong>'+esc(r.seat+' '+r.name)+'</strong><small data-class-count="'+i+'">'+length(r.comment)+' / 50 字</small></div><textarea data-class-comment="'+i+'" aria-label="'+esc(r.name+' 評語')+'" '+(r.confirmed?'readonly':'')+'>'+esc(r.comment)+'</textarea><small data-class-issue="'+i+'">'+esc(r.comment?issuesFor(r).join('；'):'尚無評語')+'</small></div>').join('');
}
$('matrixBtn').onclick=()=>openClassView('scores');$('classEditBtn').onclick=()=>openClassView('comments');$('closeClassDialog').onclick=()=>$('classDialog').close();
$('classDialog').addEventListener('close',()=>{save();render();});
$('classView').onchange=e=>{if(!e.target.hasAttribute('data-matrix'))return;const [i,j]=e.target.dataset.matrix.split(':').map(Number),r=project().students[i];if(!r||r.confirmed)return;undoScores.set(r.id,[...r.scores]);r.scores[j]=Number(e.target.value)||null;e.target.style.background=r.scores[j]?pale[r.scores[j]-1]:'#fff';changed(r);commentProgress(project().students);};
$('classView').onkeydown=e=>{const el=e.target;if(!el.hasAttribute('data-matrix'))return;let [i,j]=el.dataset.matrix.split(':').map(Number);if(/^[1-5]$/.test(e.key)){e.preventDefault();el.value=e.key;el.dispatchEvent(new Event('change',{bubbles:true}));j++;if(j===6){j=0;i++;}}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();if(e.key==='ArrowUp')i--;if(e.key==='ArrowDown')i++;if(e.key==='ArrowLeft')j--;if(e.key==='ArrowRight')j++;}else return;$('classView').querySelector('[data-matrix="'+i+':'+j+'"]')?.focus();};
$('classView').oninput=e=>{if(!e.target.hasAttribute('data-class-comment'))return;const i=Number(e.target.dataset.classComment),r=project().students[i];if(!r||r.confirmed)return;if(!r.manualDraft)rememberVersion(r);r.generationError='';r.comment=e.target.value;r.manualDraft=true;r.stale=false;r.aiWarnings=[];r.rev=(r.rev||0)+1;clearTimeout(timers.get(r.id));requests.delete(r.id);r.pending=false;save();$('classView').querySelector('[data-class-count="'+i+'"]').textContent=length(r.comment)+' / 50 字';$('classView').querySelector('[data-class-issue="'+i+'"]').textContent=issuesFor(r).join('；');commentProgress(project().students);};
$('classView').addEventListener('focusout',e=>{if(!e.target.hasAttribute('data-class-comment'))return;const r=project().students[Number(e.target.dataset.classComment)];if(r&&r.manualDraft&&!validate(r.comment,[]).length){archiveFeedback(r);save();}});

let importedReturn=[],importedAudit=new Map(),returnRevision=0;for(const id of ['returnFile','returnText'])$(id).addEventListener('input',()=>{returnRevision++;importedReturn=[];importedAudit=new Map();$('applyReturn').disabled=true;$('returnRows').innerHTML='';$('returnSummary').textContent='資料已變更，請重新預覽';$('returnAudit').hidden=true;});
function returnPreview(){return previewReturn(importedReturn,db.handoffBatches||[],project(),[...db.history.map(h=>h.comment),...db.projects.filter(p=>p.id!==project().id).flatMap(p=>p.students.map(r=>r.comment).filter(Boolean))],importedAudit);}
$('returnBtn').onclick=()=>{returnRevision++;importedReturn=[];importedAudit=new Map();$('returnFile').value=$('returnText').value=$('returnRows').innerHTML=$('returnSummary').textContent='';$('returnAudit').hidden=true;$('applyReturn').disabled=true;$('returnDialog').showModal();};$('closeReturn').onclick=()=>$('returnDialog').close();$('returnDialog').addEventListener('close',()=>{returnRevision++;});
$('previewReturn').onclick=async()=>{const revision=++returnRevision;try{
 let rows,audit=new Map();$('applyReturn').disabled=true;const file=$('returnFile').files[0];$('returnAudit').hidden=true;
 if(file&&/\.xlsx$/i.test(file.name)){const w=XLSX.read(await file.arrayBuffer(),{type:'array'});if(!w.Sheets['正式評語'])throw Error('Excel 必須有「正式評語」工作表');rows=XLSX.utils.sheet_to_json(w.Sheets['正式評語'],{header:1,raw:false,defval:''});if(w.Sheets['覆核紀錄']){audit=parseReturnAudit(XLSX.utils.sheet_to_json(w.Sheets['覆核紀錄'],{header:1,raw:false,defval:''}));if(revision!==returnRevision)return;$('returnAuditText').textContent=XLSX.utils.sheet_to_csv(w.Sheets['覆核紀錄']);$('returnAudit').hidden=false;}}
 else {const t=file?await readText(file):$('returnText').value;rows=parseReturnText(t);}
 if(revision!==returnRevision)return;importedReturn=parseReturnRows(rows);importedAudit=audit;renderReturnPreview();
 }catch(e){if(revision!==returnRevision)return;importedReturn=[];importedAudit=new Map();$('returnRows').innerHTML='';$('returnSummary').textContent=e.message;$('applyReturn').disabled=true;}};
function renderReturnPreview(){const p=returnPreview(),n=p.entries.filter(x=>!x.errors.length).length;$('returnSummary').textContent='可採用 '+n+' / '+p.entries.length+' 位；缺漏 '+p.missing.length+' 位'+(p.missing.length?'（'+p.missing.join('、')+'）':'');$('returnRows').innerHTML=p.entries.map((r,i)=>'<div class="return-row"><label><input type="checkbox" data-return-index="'+i+'" '+(r.errors.length?'disabled':r.advisories.length?'':'checked')+'> '+esc(r.seat+' '+r.name+' · '+r.code)+'</label><div class="return-comparison"><div><small>目前評語</small><p>'+esc(r.old||'尚無評語')+'</p></div><div><small>AI 回傳</small><p>'+esc(r.comment||'空白')+'</p></div></div><p class="return-error">'+esc([...r.errors,...r.advisories].join('；'))+'</p></div>').join('');$('applyReturn').disabled=!n;}
$('applyReturn').onclick=()=>{const chosen=[...$('returnRows').querySelectorAll('input:checked')].map(x=>Number(x.dataset.returnIndex));if(!chosen.length)return toast('請選取要採用的評語');let n=0;for(const i of chosen){const row=returnPreview().entries[i];if(!row||row.errors.length)continue;const r=project().students.find(x=>x.id===row.id);rememberVersion(r);clearTimeout(timers.get(r.id));requests.delete(r.id);r.pending=false;r.generationError='';r.comment=row.comment;r.manualDraft=true;r.stale=false;r.aiWarnings=[];r.rev=(r.rev||0)+1;r.externalSource=row.batchId;r.rated=true;archiveFeedback(r);n++;}save();render();$('returnDialog').close();toast('已採用 '+n+' 位評語，原文保留於版本紀錄'+(n<chosen.length?'；'+(chosen.length-n)+' 位未採用，請重新預覽':''));};

function queueMissing(){if(!db.instant)return;for(const r of project().students){if(!r.confirmed&&!r.manualDraft&&complete(r.scores)&&(!r.comment||r.stale)&&!r.pending){clearTimeout(timers.get(r.id));timers.set(r.id,setTimeout(()=>generate(r),900));}}}
queueMissing();

function renderBuiltinRules(){
 const q=$('semanticSearch').value.trim().toLowerCase(),dim=$('semanticDimensionFilter').value,rows=builtinSemanticRules.filter(r=>(!dim||r.dimension===dim)&&Object.values(r).join(' ').toLowerCase().includes(q));$('semanticResultCount').textContent='顯示 '+rows.length+' / '+builtinSemanticRules.length+' 條';
 $('semanticBuiltinList').innerHTML=rows.map(r=>'<details class="builtin-rule"><summary>'+esc(r.strength||r.goal)+' <small>'+esc(r.dimension)+'</small></summary><dl><dt>肯定描述</dt><dd>'+esc(r.strength||'—')+'</dd><dt>成長方向</dt><dd>'+esc(r.goal||'—')+'</dd><dt>肯定辨識式</dt><dd>'+esc(r.positive||'—')+'</dd><dt>成長辨識式</dt><dd>'+esc(r.negative||'—')+'</dd><dt>排除辨識式</dt><dd>'+esc(r.exclusion||'—')+'</dd><dt>改善描述</dt><dd>'+esc(r.progress||'—')+'</dd></dl></details>').join('')||'<p class="muted">無符合的內建規則。</p>';
}
$('semanticSearch').oninput=renderBuiltinRules;$('semanticDimensionFilter').innerHTML='<option value="">全部向度</option>'+[...dims,'不限向度'].map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('');$('semanticDimensionFilter').onchange=renderBuiltinRules;
$('semanticLabScores').innerHTML=dims.map((dim,i)=>'<label>'+esc(dim)+'<select aria-label="'+esc(dim)+'（試驗）" data-lab-score="'+i+'">'+[5,4,3,2,1].map(v=>'<option value="'+v+'" '+(v===4?'selected':'')+'>'+v+' '+esc(levels[v-1])+'</option>').join('')+'</select></label>').join('');
$('semanticLabRun').onclick=()=>{
 try{
  const scores=[...$('semanticLabScores').querySelectorAll('select')].map(x=>Number(x.value)),note=$('semanticLabNote').value;
  const p=profile(),custom=[...(p.semanticRules||[])];
  if($('semanticLabUnsaved').checked){const rule=readSemanticRule();if(!validSemanticRule(rule))throw Error('編輯中的語意規則尚不完整');if(semanticEditing>=0)custom[semanticEditing]=rule;else custom.push(rule);}
  const x=deepGenerate(scores,note,[],{...p,semanticRules:custom}),a={positives:x.plan.evidence.strengths.map(e=>e.phrase),goals:x.plan.evidence.goals.map(e=>e.phrase),unknown:x.plan.evidence.unknown,conflicts:x.plan.evidence.conflicts};
  $('semanticLabResult').innerHTML='<div class="lab-result"><div class="lab-comment"><small>試生成評語 · '+x.characters+' 字</small><p>'+esc(x.comment)+'</p></div>'+[['評量層級',[x.quality.level||'學期總結性評量']],['學期發展概念',x.chosenGoals.map(e=>e.concept+'：'+e.phrase)],['單次事件（不推論長期表現）',x.coverage.deferred||[]],['期許連接方式',[x.quality.connective||'—']],['篇章偏好學習',[String(x.quality.learnedSamples||0)+' 筆有效人工修訂']],['篇章規劃',[x.plan.focus,x.quality.form||'',x.source==='deep'?'深層引擎 v'+NLG_VERSION:x.source==='compatibility'?'相容備援':'無合規候選']],[ '實際採用的證據',[...x.chosenStrengths,...x.chosenGoals].map(e=>e.phrase+'（'+e.source+'）')],['觀察頻率與變化',[...x.plan.evidence.strengths,...x.plan.evidence.goals].map(e=>e.phrase+'：'+e.frequency+'／'+e.time)],['辨識到的肯定',a.positives],['辨識到的成長方向',a.goals],['尚未辨識',a.unknown],['評分或觀察衝突',a.conflicts],['尚未涵蓋的觀察',[...x.coverage.missingStrengths,...x.coverage.missingGoals]],['硬性檢查',x.issues]].map(([label,items])=>'<div><strong>'+label+'</strong><p>'+esc(items.join('；')||'無')+'</p></div>').join('')+'</div>';
 }catch(e){$('semanticLabResult').textContent=e.message;}
};
$('semanticLabClear').onclick=()=>{$('semanticLabNote').value='';$('semanticLabUnsaved').checked=false;$('semanticLabResult').textContent='';for(const el of $('semanticLabScores').querySelectorAll('select'))el.value='4';};
